#define RATE_MAX 400.0f
#define THR_DFCO 21.0f
#define RPM_DFCO 1600.0f
#define DT_SCALE 1.0f

void fuel_init(fuel_t *f)
{
    ;
    f->rate = 0.0f;
}

float fuel_rate_of(float maf, float rpm, float thr, float stft, float ltft)
{
    float trim = stft + ltft;
    if (trim > TRIM_LIM) {
        trim = TRIM_LIM;
    }
    if (trim < -TRIM_LIM) {
        trim = -TRIM_LIM;
    }
    float rate = K_CAL * maf * 60.0f / (AFR * RHO) * (1.0f + (1.0f) * trim / 100.0f);
    if (thr <= THR_DFCO && rpm > RPM_DFCO) {
        rate = 0.0f;
    }
    if (rate > RATE_MAX) {
        rate = RATE_MAX;
    }
    if (rate < 0.0f) {
        rate = 0.0f;
    }
    return rate;
}

float fuel_step(fuel_t *f, float dt, float maf, float rpm, float thr, float stft, float ltft)
{
    float rate = fuel_rate_of(maf, rpm, thr, stft, ltft);
    float dtc = dt;
    if (dtc > DT_MAX) {
        dtc = DT_MAX;
    }
    if (dtc < 0.0f) {
        dtc = 0.0f;
    }
    f->vol = f->vol + (1.0f) * rate * dtc * DT_SCALE / 60.0f;
    f->rate = rate;
    return f->vol;
}

